import{z as t,x as r,o as p,c as l,q as s,j as n,D as o,d as i,s as E,S as c}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"oops 与 panic","description":"","frontmatter":{"title":"oops 与 panic","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oops-panic.md","filePath":"cs/oops-panic.md","lastUpdated":1791413859000}'),d={name:"cs/oops-panic.md"};function B(A,a,_,m,h,u){const e=r("Mermaid");return p(),l("div",null,[a[2]||(a[2]=s('<h1 id="oops-与-panic" tabindex="-1">oops 与 panic <a class="header-anchor" href="#oops-与-panic" aria-label="Permalink to &quot;oops 与 panic&quot;">​</a></h1><div class="epigraph"><p>oops 记录一次内核非法访问或 BUG，进程可能被杀而系统继续；panic 认为无法继续，停机或转 dump。</p><footer>—— 据 Linux 对 oops/panic 的文档；[kdump](/cs/kdump-crash) 为转储先修</footer></div><p><a href="/cs/kdump-crash">kdump</a> 在 panic 路径上触发。缺口是 <strong>oops vs panic 的策略</strong>：<code>panic_on_oops</code>、RCU stall、软锁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空指针在进程上下文：oops，杀该任务。中断上下文或 idle：常直接 panic。缺口：tainted 标志；连续 oops；与 <a href="/cs/kernel-hardening">hardening</a> 的 BUG_ON。本课不分析具体漏洞。</p><p><span class="marginnote">sysctl <code>kernel.panic</code> 超时重启。对象是失败模式，不是调试符号安装。</span></p><p><span class="marginnote">直觉类比：oops 像航班上一名乘客晕倒——处理该任务的进程被「抬走」，航班照飞；panic 像机长宣布紧急迫降——宁可整机停摆，也要保住黑匣子（dump）里的现场。选哪档，就是可用性与可诊断性的交换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>fault → <code>oops_begin</code> 打栈 → 若策略则 <code>panic</code>。对照 <a href="/cs/asan-mechanism">ASan</a>：用户非法 vs 内核非法。对照 <a href="/cs/nmi">NMI</a>：NMI 里 printk 受限。对照 SELinux：拒绝不是 oops。</p>',9)),(p(),n(c,null,{default:o(()=>[E(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUG%5B%22%E9%9D%9E%E6%B3%95%E8%AE%BF%E9%97%AE%2FBUG%22%5D%20--%3E%20OOPS%5B%22oops%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20OOPS%20--%3E%7C%22%E5%8F%AF%E6%81%A2%E5%A4%8D%22%7C%20CONT%5B%22%E6%9D%80%E4%BB%BB%E5%8A%A1%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20OOPS%20--%3E%7C%22panic_on_oops%20%E6%88%96%E8%87%B4%E5%91%BD%E4%B8%8A%E4%B8%8B%E6%96%87%22%7C%20PAN%5B%22panic%22%5D%0A%20%20PAN%20--%3E%20DUMP%5B%22kdump%20%E6%88%96%E9%87%8D%E5%90%AF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p><span class="marginnote">数字实例：生产服务器的常见组合是 <code>kernel.panic_on_oops=1</code>（任何 oops 都升级为 panic）加 <code>kernel.panic=10</code>（panic 后 10 秒自动重启），再配 kdump 先抓内存转储——用一次确定的停机换一份可信的现场。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内核把「局部腐败」和「全局不可信」分开：oops 允许服务器继续卖服务，也允许静默损坏——故生产常 panic_on_oops。不要写成恐吓。与 <a href="/cs/memcg">memcg</a> OOM：那是杀用户，不是内核 oops。</p><p>栈损坏的 oops 本身不可信。</p><p>oops 后「继续跑」为什么可能更糟：</p>',5)),(p(),n(c,null,{default:o(()=>[E(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OOPS%5B%22%E4%B8%80%E6%AC%A1%20oops%20%E5%90%8E%E7%BB%A7%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20GOOD%5B%22%E5%A4%9A%E6%95%B0%E6%83%85%E5%86%B5%3A%20%E5%8F%AA%E6%AD%BB%E4%B8%80%E4%B8%AA%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20OOPS%20--%3E%20BAD%5B%22%E5%8F%91%E7%94%9F%E5%9C%A8%E6%8C%81%E9%94%81%20%2F%20%E5%8D%8A%E9%80%94%E5%86%99%E8%B7%AF%E5%BE%84%22%5D%0A%20%20BAD%20--%3E%20STALL%5B%22%E9%94%81%E4%B8%8D%E9%87%8A%E6%94%BE%2C%20%E6%85%A2%E6%85%A2%E6%8B%96%E6%88%90%E8%BD%AF%E9%94%81%22%5D%0A%20%20BAD%20--%3E%20SILENT%5B%22%E6%95%B0%E6%8D%AE%E6%94%B9%E4%BA%86%E4%B8%80%E5%8D%8A%2C%20%E9%9D%99%E9%BB%98%E6%8D%9F%E5%9D%8F%22%5D%0A%20%20SILENT%20--%3E%20LATER%5B%22%E6%95%B0%E5%A4%A9%E5%90%8E%E7%88%86%E5%8F%91%2C%20%E6%97%A0%E4%BB%8E%E6%9F%A5%E8%B5%B7%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">常见误区：初学者以为「系统没崩就没事」。oops 若发生在持锁路径，锁可能永远不释放，其他任务逐个卡死；表面「还活着」的机器实际已经残废——这正是生产宁选 panic_on_oops 的原因。</span></p><p>实现上：tainted 标志告诉你是否加载了专有模块或发生过严重警告。中断上下文 oops 几乎必然 panic。连续 oops 可能已损坏到栈不可信。 读法上只引用<a href="/cs/kdump-crash">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>oops 与 panic</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 lockdep 警告。不保证嵌入式无 console 时的策略。下一课不停机补内核：livepatch。</p><p>版本字段会变，课序钉的是机制对象「oops 与 panic」，不是某一主线内核的结构体名。 后课默认：oops 可转 panic 以便 dump。运行时替换函数，下一课 livepatch。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>oops 记录并可能继续；panic 停机。</li><li>策略决定安全性与可用性。</li><li>livepatch 是下一课。</li><li>出处：Linux oops；panic sysctl；kdump。</li></ul>',9))])}const T=t(d,[["render",B]]);export{f as __pageData,T as default};
